def flatten_dict(d, sep='.'):
    '''
    Flattens a nested dictionary.

    Args:
        d (dict): The dictionary to flatten.
        sep (str, optional): The separator to use for concatenating keys. Defaults to '.'.

    Returns:
        dict: The flattened dictionary.

    Examples:
        >>> flatten_dict({'a': 1, 'b': {'c': 2, 'd': {'e': 3}}})
        {'a': 1, 'b.c': 2, 'b.d.e': 3}
        >>> flatten_dict({'x': 1, 'y': {'z': 2}}, sep='_')
        {'x': 1, 'y_z': 2}
    '''
    flattened = {}

    def _flatten(obj, prefix=''):
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_prefix = f'{prefix}{sep}{k}' if prefix else k
                _flatten(v, new_prefix)
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                new_prefix = f'{prefix}{sep}{i}' if prefix else str(i)
                _flatten(item, new_prefix)
        else:
            flattened[prefix] = obj

    _flatten(d)
    return flattened
